-- ============================================= -- Task: new endpoints (my-work, dependencies) -- ============================================= INSERT INTO permissions (permission_id, name, api_path, http_method, module, created_at, updated_at, created_by, updated_by, version) SELECT UUID(), 'Task my work', '/api/v1/tasks/my-work', 'GET', 'COLLAB', NOW(6), NOW(6), 'system', 'system', 0 WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE api_path = '/api/v1/tasks/my-work' AND http_method = 'GET');
INSERT INTO permissions (permission_id, name, api_path, http_method, module, created_at, updated_at, created_by, updated_by, version) SELECT UUID(), 'Task dependencies detail', '/api/v1/tasks/{taskId}/dependencies', 'GET', 'COLLAB', NOW(6), NOW(6), 'system', 'system', 0 WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE api_path = '/api/v1/tasks/{taskId}/dependencies' AND http_method = 'GET');
INSERT INTO permissions (permission_id, name, api_path, http_method, module, created_at, updated_at, created_by, updated_by, version) SELECT UUID(), 'Task dependencies update', '/api/v1/tasks/{taskId}/dependencies', 'PUT', 'COLLAB', NOW(6), NOW(6), 'system', 'system', 0 WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE api_path = '/api/v1/tasks/{taskId}/dependencies' AND http_method = 'PUT');
