-- ============================================= -- Grant all new COLLAB permissions to ADMIN role -- ============================================= INSERT INTO permission_roles (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r JOIN permissions p ON p.module = 'COLLAB' WHERE r.name = 'ADMIN' AND NOT EXISTS ( SELECT 1 FROM permission_roles pr WHERE pr.role_id = r.role_id AND pr.permission_id = p.permission_id );
-- ============================================= -- Grant invite-join and invite-validate to USER role -- (regular users need to be able to join workspaces via invite) -- ============================================= INSERT INTO permission_roles (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r JOIN permissions p ON p.api_path IN ( '/api/v1/workspace-invites/validate/{inviteCode}', '/api/v1/workspace-invites/join' ) WHERE r.name = 'USER' AND NOT EXISTS ( SELECT 1 FROM permission_roles pr WHERE pr.role_id = r.role_id AND pr.permission_id = p.permission_id );
